1	package clinical
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"reflect"
8		"testing"
9		"time"
10	)
11	
12	// TestDeactivationSaveFailureKeepsAccessAndHistory 覆盖“内部使用者对一份尚未停用
13	// 的合成患者档案提交停用，身份与患者标识均合法，仅因本地保存失败而未能完成”的
14	// 档案停用场景。
15	//
16	// 前置数据：档案已有一次就诊；该就诊下有一条仍可修改的草稿，以及一条已生效且
17	// 有更正历史的诊断（第 1 版经更正得到当前第 2 版，旧版本、PrevID 版本链与更正
18	// 原因都在）。接收方持有覆盖这次就诊全部诊断的有效整类授权，原本能读到更正后的
19	// 当前版本，看不到草稿、旧版本或更正原因。授权时间窗覆盖失败尝试与后续成功提交
20	// 的全部时刻且始终未撤回，使读取变化只能来自档案停用结果本身。
21	//
22	// 本地保存失败时：停用必须以普通保存错误返回，不能报告成功，也不能误报为
23	// ErrAccessDenied、ErrNotFound 或 ErrDeactivated；内部查询仍显示患者未停用，
24	// 就诊归属、草稿完整内容、生效记录的当前版本与旧版本链、更正原因均与提交前
25	// 相同；审计内容及排列顺序原样保留，不出现停用事件；接收方随后仍能读取原来的
26	// 当前版本（记录标识、版本标识与内容不变），仍看不到草稿、旧版本或更正原因。
27	//
28	// 保存条件恢复后：同一患者可以正常提交停用。内部查询显示停用，并且相对提交前
29	// 只增加一条停用审计，准确记录患者、操作身份与这次成功操作的时间；原有审计不
30	// 被替换或重新排列。接收方随后读取同一就诊、同一类别时返回 ErrAccessDenied，
31	// 结果不携带记录标识或内容，原授权仍存在也不能继续读取。内部使用者依旧能查看
32	// 原有草稿及完整版本历史，停用不会覆盖或删除它们。
33	func TestDeactivationSaveFailureKeepsAccessAndHistory(t *testing.T) {
34		dir := t.TempDir()
35		clk := &fakeClock{t: time.Date(2026, 5, 1, 9, 0, 0, 0, time.UTC)}
36		open := func() *Store {
37			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
38			if err != nil {
39				t.Fatalf("open: %v", err)
40			}
41			return s
42		}
43	
44		s := open()
45		p, err := s.RegisterPatient(doc, "停用保存失败患者")
46		if err != nil {
47			t.Fatal(err)
48		}
49		e, err := s.AddEncounter(doc, p.ID, time.Time{})
50		if err != nil {
51			t.Fatal(err)
52		}
53		// 同一次就诊下一条仍是草稿的诊断。
54		draftContent := "尚未生效的草稿内容"
55		draft, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, draftContent)
56		if err != nil {
57			t.Fatal(err)
58		}
59		// 同一次就诊下一条已生效的诊断，随后更正一次：当前为第 2 版。
60		r, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "初诊：高血压 I10")
61		if err != nil {
62			t.Fatal(err)
63		}
64		v1, err := s.ActivateRecord(doc, r.ID)
65		if err != nil {
66			t.Fatal(err)
67		}
68		clk.t = clk.t.Add(time.Hour)
69		v2, err := s.CorrectRecord(doc, r.ID, 1, "复诊：高血压 I10（控制稳定）", "复核更新")
70		if err != nil {
71			t.Fatal(err)
72		}
73		// 接收方持有覆盖这次就诊全部诊断的整类授权。时间窗覆盖失败尝试与后续
74		// 成功提交的全部时刻，且全程不撤回：读取变化只能来自停用结果本身。
75		auth, err := s.Grant(doc, p.ID, rcv.ID,
76			[]Scope{{EncounterID: e.ID, Category: Diagnosis}},
77			clk.t.Add(-2*time.Hour), clk.t.Add(72*time.Hour))
78		if err != nil {
79			t.Fatal(err)
80		}
81	
82		// ---- 提交前的正式基线 ----
83		patientBefore, err := s.GetPatient(doc, p.ID)
84		if err != nil {
85			t.Fatal(err)
86		}
87		if patientBefore.Deactivated {
88			t.Fatal("baseline patient must not be deactivated")
89		}
90		encountersBefore, err := s.ListEncounters(doc, p.ID)
91		if err != nil {
92			t.Fatal(err)
93		}
94		chartBefore, err := s.Chart(doc, p.ID)
95		if err != nil {
96			t.Fatal(err)
97		}
98		draftHistBefore := findHistory(chartBefore, draft.ID)
99		if draftHistBefore == nil || !draftHistBefore.HasDraft ||
100			draftHistBefore.DraftContent != draftContent || draftHistBefore.CurrentVersion != nil ||
101			len(draftHistBefore.Versions) != 0 {
102			t.Fatalf("unexpected baseline draft history: %+v", draftHistBefore)
103		}
104		activeHistBefore := findHistory(chartBefore, r.ID)
105		if activeHistBefore == nil || activeHistBefore.CurrentVersion == nil ||
106			activeHistBefore.CurrentVersion.ID != v2.ID || len(activeHistBefore.Versions) != 2 {
107			t.Fatalf("unexpected baseline active history: %+v", activeHistBefore)
108		}
109		authBefore, err := s.GetAuthorization(doc, p.ID, auth.ID)
110		if err != nil {
111			t.Fatal(err)
112		}
113		auditBefore, err := s.AuditEvents(doc, p.ID)
114		if err != nil {
115			t.Fatal(err)
116		}
117		if got := auditActions(auditBefore); got[ActionActivated] != 1 ||
118			got[ActionCorrected] != 1 || got[ActionGranted] != 1 || got[ActionDeactivated] != 0 {
119			t.Fatalf("unexpected baseline audit: %v", got)
120		}
121		// 接收方原本能读到更正后的当前版本：记录标识、版本标识与内容均为第 2 版，
122		// 结果里没有草稿、旧版本或更正原因（EffectiveRecord 本身不含这些）。
123		readBefore, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
124		if err != nil {
125			t.Fatal(err)
126		}
127		if len(readBefore.Records) != 1 {
128			t.Fatalf("baseline read = %+v, want exactly the current version", readBefore)
129		}
130		cur := readBefore.Records[0]
131		if cur.RecordID != r.ID || cur.VersionID != v2.ID || cur.Version != 2 ||
132			cur.Content != v2.Content || !cur.EffectiveAt.Equal(v2.CreatedAt) {
133			t.Fatalf("baseline read does not expose the corrected current version: %+v", cur)
134		}
135		if readRecordIDs(readBefore)[draft.ID] {
136			t.Fatal("baseline read must not expose the draft")
137		}
138	
139		// checkIntact 断言：失败尝试之后（以及重开之后），档案停用状态、就诊归属、
140		// 草稿完整内容、生效记录的当前版本与旧版本链、更正原因、审计与接收方可见
141		// 结果全部与提交前逐项一致——失败尝试不能提前改变内部历史或接收方访问。
142		checkIntact := func(label string, st *Store) {
143			t.Helper()
144	
145			// 内部查询仍显示患者未停用，患者档案本身其他字段不变。
146			patient, err := st.GetPatient(doc, p.ID)
147			if err != nil {
148				t.Fatalf("%s: get patient: %v", label, err)
149			}
150			if patient.Deactivated {
151				t.Fatalf("%s: patient must not be deactivated after failed save", label)
152			}
153			wantPatient := patientBefore
154			wantPatient.Deactivated = false
155			if !reflect.DeepEqual(patient, wantPatient) {
156				t.Fatalf("%s: patient changed:\nbefore: %+v\nafter:  %+v", label, wantPatient, patient)
157			}
158	
159			// 就诊归属与完整档案（草稿、当前版本、旧版本链、更正原因）原样保留。
160			encs, err := st.ListEncounters(doc, p.ID)
161			if err != nil {
162				t.Fatalf("%s: list encounters: %v", label, err)
163			}
164			if !reflect.DeepEqual(encs, encountersBefore) {
165				t.Fatalf("%s: encounters changed:\nbefore: %+v\nafter:  %+v", label, encountersBefore, encs)
166			}
167			chart, err := st.Chart(doc, p.ID)
168			if err != nil {
169				t.Fatalf("%s: chart: %v", label, err)
170			}
171			if !reflect.DeepEqual(chart.Encounters, chartBefore.Encounters) ||
172				!reflect.DeepEqual(chart.Records, chartBefore.Records) {
173				t.Fatalf("%s: internal history changed:\nbefore: %+v\nafter:  %+v",
174					label, chartBefore, chart)
175			}
176			dh := findHistory(chart, draft.ID)
177			if dh == nil || dh.Record.EncounterID != e.ID || dh.Record.PatientID != p.ID ||
178				dh.Record.Category != Diagnosis || !dh.HasDraft || dh.DraftContent != draftContent ||
179				dh.CurrentVersion != nil || len(dh.Versions) != 0 {
180				t.Fatalf("%s: draft no longer intact: %+v", label, dh)
181			}
182			ah := findHistory(chart, r.ID)
183			if ah == nil || ah.Record.EncounterID != e.ID || ah.Record.PatientID != p.ID ||
184				ah.CurrentVersion == nil || ah.CurrentVersion.ID != v2.ID ||
185				!reflect.DeepEqual(ah.Record.Versions, []ID{v1.ID, v2.ID}) || len(ah.Versions) != 2 {
186				t.Fatalf("%s: effective record history no longer intact: %+v", label, ah)
187			}
188			// 旧版本内容、PrevID 版本链与两版的更正原因均与提交前相同。
189			if !reflect.DeepEqual(ah.Versions[0], v1) || !reflect.DeepEqual(ah.Versions[1], v2) ||
190				ah.Versions[1].PrevID != v1.ID || ah.Versions[1].Reason != v2.Reason {
191				t.Fatalf("%s: version chain or reasons changed: %+v", label, ah.Versions)
192			}
193	
194			// 审计内容及排列顺序原样保留，不出现停用事件。
195			audit, err := st.AuditEvents(doc, p.ID)
196			if err != nil {
197				t.Fatalf("%s: audit: %v", label, err)
198			}
199			if !reflect.DeepEqual(audit, auditBefore) {
200				t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
201			}
202			if got := auditActions(audit)[ActionDeactivated]; got != 0 {
203				t.Fatalf("%s: patient_deactivated events = %d, want 0", label, got)
204			}
205	
206			// 原授权仍存在、未撤回且在当前时刻有效：读取变化不能由授权状态解释。
207			gotAuth, err := st.GetAuthorization(doc, p.ID, auth.ID)
208			if err != nil {
209				t.Fatalf("%s: get authorization: %v", label, err)
210			}
211			if !reflect.DeepEqual(gotAuth, authBefore) || gotAuth.RevokedAt != nil {
212				t.Fatalf("%s: authorization changed:\nbefore: %+v\nafter:  %+v", label, authBefore, gotAuth)
213			}
214			if !gotAuth.ActiveAt(clk.t) {
215				t.Fatalf("%s: authorization must stay active at %v: %+v", label, clk.t, gotAuth)
216			}
217	
218			// 接收方随后仍能读取原来的当前版本：记录标识、版本标识与内容不变；
219			// 仍看不到草稿、旧版本或更正原因。
220			res, err := st.Read(rcv, p.ID, e.ID, Diagnosis)
221			if err != nil {
222				t.Fatalf("%s: receiver read: %v", label, err)
223			}
224			if !reflect.DeepEqual(res, readBefore) {
225				t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", label, readBefore, res)
226			}
227			if len(res.Records) != 1 || res.Records[0].RecordID != r.ID ||
228				res.Records[0].VersionID != v2.ID || res.Records[0].Content != v2.Content {
229				t.Fatalf("%s: receiver no longer sees exactly the corrected current version: %+v", label, res)
230			}
231			if readRecordIDs(res)[draft.ID] || res.Records[0].Version != 2 {
232				t.Fatalf("%s: receiver read leaks draft or old version: %+v", label, res)
233			}
234		}
235	
236		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
237		// 与身份、患者标识合法性或患者状态无关。原数据文件先挪到旁边，事后还原。
238		failTime := clk.t.Add(time.Hour)
239		clk.t = failTime
240		dataPath := filepath.Join(dir, dataName)
241		backupPath := dataPath + ".saved"
242		if err := os.Rename(dataPath, backupPath); err != nil {
243			t.Fatalf("backup data file: %v", err)
244		}
245		if err := os.Mkdir(dataPath, 0o755); err != nil {
246			t.Fatalf("block data path: %v", err)
247		}
248	
249		// 身份有权、患者存在且未停用，仅本地保存失败：必须返回保存错误，不能报告
250		// 成功，也不能误报为 ErrAccessDenied、ErrNotFound 或 ErrDeactivated。
251		if err := s.DeactivatePatient(doc, p.ID); err == nil {
252			t.Fatal("deactivation must fail when local save fails")
253		} else if errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrNotFound) ||
254			errors.Is(err, ErrDeactivated) || errors.Is(err, ErrInvalidArgument) ||
255			errors.Is(err, ErrMismatchedPatient) || errors.Is(err, ErrConflict) {
256			t.Fatalf("save failure surfaced as a business error: %v", err)
257		}
258		// 失败不能留下半截写入的临时文件。
259		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
260			t.Fatalf("failed save left a temp file: %v", statErr)
261		}
262	
263		// 失败后：停用状态、内部历史、审计与接收方访问全部维持提交前状态。
264		checkIntact("after failed save", s)
265	
266		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件），
267		// 失败后的未停用状态在重开后保持一致。
268		if err := s.Close(); err != nil {
269			t.Fatal(err)
270		}
271		if err := os.Remove(dataPath); err != nil {
272			t.Fatalf("unblock data path: %v", err)
273		}
274		if err := os.Rename(backupPath, dataPath); err != nil {
275			t.Fatalf("restore data file: %v", err)
276		}
277		s2 := open()
278		checkIntact("after reopen", s2)
279	
280		// 保存条件恢复后：同一患者可以正常提交停用。停用时间属于这次成功操作，
281		// 不能沿用失败尝试的时间。
282		successTime := failTime.Add(time.Hour)
283		clk.t = successTime
284		if err := s2.DeactivatePatient(doc, p.ID); err != nil {
285			t.Fatalf("deactivate after save recovered: %v", err)
286		}
287	
288		// 内部查询显示停用。
289		patient, err := s2.GetPatient(doc, p.ID)
290		if err != nil {
291			t.Fatal(err)
292		}
293		if !patient.Deactivated {
294			t.Fatal("patient must be deactivated after successful submit")
295		}
296	
297		// 相对提交前只增加一条停用审计：准确记录患者、操作身份与成功操作的时间；
298		// 原有审计不被替换或重新排列。
299		audit, err := s2.AuditEvents(doc, p.ID)
300		if err != nil {
301			t.Fatal(err)
302		}
303		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
304			t.Fatalf("audit after successful deactivation:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
305		}
306		last := audit[len(audit)-1]
307		if last.Action != ActionDeactivated || last.ObjectType != "patient" || last.ObjectID != p.ID ||
308			last.ActorID != doc.ID || last.PatientID != p.ID || !last.OccurredAt.Equal(successTime) {
309			t.Fatalf("unexpected new audit event: %+v", last)
310		}
311		if last.OccurredAt.Equal(failTime) {
312			t.Fatalf("deactivation audit time %v must not belong to the failed attempt %v",
313				last.OccurredAt, failTime)
314		}
315		if got := auditActions(audit)[ActionDeactivated]; got != 1 {
316			t.Fatalf("patient_deactivated events = %d, want 1", got)
317		}
318	
319		// 接收方随后读取同一就诊、同一类别：ErrAccessDenied，结果不携带记录标识
320		// 或内容；原授权仍存在（未撤回、仍在有效期）也不能继续读取。
321		res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis)
322		if !errors.Is(err, ErrAccessDenied) {
323			t.Fatalf("receiver read after deactivation: res=%+v err=%v, want ErrAccessDenied", res, err)
324		}
325		if res.EncounterID != "" || res.Category != "" || len(res.Records) != 0 {
326			t.Fatalf("denied read must carry no record ids or content: %+v", res)
327		}
328		gotAuth, err := s2.GetAuthorization(doc, p.ID, auth.ID)
329		if err != nil {
330			t.Fatalf("authorization must still exist after deactivation: %v", err)
331		}
332		if gotAuth.RevokedAt != nil || !gotAuth.ActiveAt(successTime) {
333			t.Fatalf("existing authorization must remain intact and active, yet reads stay denied: %+v", gotAuth)
334		}
335		if !reflect.DeepEqual(gotAuth.Scopes, authBefore.Scopes) ||
336			!gotAuth.StartsAt.Equal(authBefore.StartsAt) || !gotAuth.ExpiresAt.Equal(authBefore.ExpiresAt) {
337			t.Fatalf("authorization mutated by deactivation:\nbefore: %+v\nafter:  %+v",
338				authBefore, gotAuth)
339		}
340	
341		// 内部使用者依旧能查看原有草稿及完整版本历史：停用不覆盖、不删除它们。
342		chart, err := s2.Chart(doc, p.ID)
343		if err != nil {
344			t.Fatal(err)
345		}
346		if !chart.Patient.Deactivated {
347			t.Fatal("chart should show deactivated")
348		}
349		if !reflect.DeepEqual(chart.Encounters, chartBefore.Encounters) ||
350			!reflect.DeepEqual(chart.Records, chartBefore.Records) {
351			t.Fatalf("internal history changed by deactivation:\nbefore: %+v\nafter:  %+v",
352				chartBefore, chart)
353		}
354		dh := findHistory(chart, draft.ID)
355		if dh == nil || !dh.HasDraft || dh.DraftContent != draftContent ||
356			dh.Record.EncounterID != e.ID || dh.CurrentVersion != nil {
357			t.Fatalf("draft lost after deactivation: %+v", dh)
358		}
359		ah := findHistory(chart, r.ID)
360		if ah == nil || ah.CurrentVersion == nil || ah.CurrentVersion.ID != v2.ID ||
361			len(ah.Versions) != 2 || !reflect.DeepEqual(ah.Versions[0], v1) ||
362			!reflect.DeepEqual(ah.Versions[1], v2) || ah.Versions[1].PrevID != v1.ID {
363			t.Fatalf("full version history lost after deactivation: %+v", ah)
364		}
365	
366		// 成功停用后的既有规则保留：重复停用幂等，不产生额外停用事件。
367		if err := s2.DeactivatePatient(doc, p.ID); err != nil {
368			t.Fatalf("repeat deactivation must stay successful: %v", err)
369		}
370		if evs, err := s2.AuditEvents(doc, p.ID); err != nil || len(evs) != len(audit) {
371			t.Fatalf("repeat deactivation added audit events: before=%d after=%d err=%v",
372				len(audit), len(evs), err)
373		}
374	
375		// 关闭后从同一数据位置重新打开：停用状态与唯一停用审计完整保留，接收方
376		// 依旧被拒绝且不携带内容，内部草稿与完整版本历史仍在；失败尝试不作为额外
377		// 的停用状态或事件出现。
378		if err := s2.Close(); err != nil {
379			t.Fatal(err)
380		}
381		s3 := open()
382		t.Cleanup(func() { _ = s3.Close() })
383	
384		reloaded, err := s3.GetPatient(doc, p.ID)
385		if err != nil {
386			t.Fatalf("get patient after reopen: %v", err)
387		}
388		if !reloaded.Deactivated {
389			t.Fatalf("deactivated state not preserved after reopen: %+v", reloaded)
390		}
391		if denied, err := s3.Read(rcv, p.ID, e.ID, Diagnosis); !errors.Is(err, ErrAccessDenied) ||
392			len(denied.Records) != 0 || denied.EncounterID != "" || denied.Category != "" {
393			t.Fatalf("read after reopen: res=%+v err=%v, want ErrAccessDenied without content",
394				denied, err)
395		}
396		reloadedChart, err := s3.Chart(doc, p.ID)
397		if err != nil {
398			t.Fatal(err)
399		}
400		if !reflect.DeepEqual(reloadedChart.Records, chartBefore.Records) {
401			t.Fatalf("internal history not preserved after reopen:\nbefore: %+v\nafter:  %+v",
402				chartBefore.Records, reloadedChart.Records)
403		}
404		var deactivateTimes []time.Time
405		for _, ev := range mustAudit(t, s3, p.ID) {
406			if ev.Action == ActionDeactivated {
407				deactivateTimes = append(deactivateTimes, ev.OccurredAt)
408			}
409		}
410		if len(deactivateTimes) != 1 || !deactivateTimes[0].Equal(successTime) {
411			t.Fatalf("deactivation events after reopen = %v, want only [%v]",
412				deactivateTimes, successTime)
413		}
414	}
415

