278			t.Fatalf("a2 revocation time = %v, want %v", doneA2.RevokedAt, secondRevokeAt)
279		}
280	
281		// 最终审计：a1 的撤回事件仍属首次操作（doc、firstRevokeAt），
282		// a2 新增一条属于实际成功操作（doc2、secondRevokeAt）的事件。
283		finalAudit, err := s.AuditEvents(doc, p.ID)
284		if err != nil {
285			t.Fatal(err)
286		}
